import re
with open('references.bib') as f:
    content = f.read()

entries = re.split(r'(?=@\w+\{)', content)
issues = []
for e in entries:
    e = e.strip()
    if not e or e.startswith('%'):
        continue
    m = re.match(r'@(\w+)\{([^,]+),', e)
    if not m:
        continue
    etype, key = m.group(1), m.group(2)
    if etype.lower() == 'string':
        continue
    has_year = bool(re.search(r'year\s*=', e, re.I))
    has_author = bool(re.search(r'author\s*=', e, re.I))
    has_venue = bool(re.search(r'(booktitle|journal|howpublished|institution|school|publisher)\s*=', e, re.I))
    missing = []
    if not has_year: missing.append('year')
    if not has_author: missing.append('author')
    if not has_venue: missing.append('venue')
    if missing:
        issues.append(f'{key}: missing {missing}')

for i in issues:
    print(i)
print(f'Total entries: {len([e for e in entries if e.strip() and not e.strip().startswith(\"%\")])}')
print(f'Issues: {len(issues)}')
"

